import Table, { type ColumnType } from 'react-responsive-datatable-kit';
import 'react-responsive-datatable-kit/styles.css';

const columns: ColumnType[] = [
  { data: 'name', title: 'Name', orderable: true },
  { data: 'email', title: 'Email' },
];
const rows = [
  { id: 0, name: 'Mina', email: 'mina@example.com', notes: 'Designer' },
  { id: 1, name: 'Arman', email: 'arman@example.com', notes: 'Developer' },
];

export default function People() {
  return <Table mode="static" columns={columns} staticRows={rows} />;
}

// All rows are already in memory
<Table mode="static" columns={columns} staticRows={rows} />

// The table manages requests
<Table mode="internal" columns={columns}
  internalApiConfig={{ endpoint: '/api/people', method: 'GET' }} />

// Your app manages requests and state
<Table mode="external" columns={columns}
  externalRows={rows} totalItems={total} isLoading={loading}
  onPageChange={setPage} onPageSizeChange={setPageSize}
  onSearch={setSearch} onSortChange={setOrder} />

const columns: ColumnType[] = [
  { data: 'name', title: 'Name', hideable: false },
  { data: 'email', title: 'Email', hidden: true },
];

<Table mode="static" columns={columns} staticRows={rows}
  columnVisibility />

const [selectedIds, setSelectedIds] = useState<Array<string | number>>([]);

<Table mode="static" columns={columns} staticRows={rows}
  isSelectable selectedIds={selectedIds}
  onSelectChange={setSelectedIds}
  selectedKey="id" />

const [name, setName] = useState('');

<Table mode="static" columns={columns}
  staticRows={rows.filter(row => row.name.includes(name))}
  filters={<>
    <input aria-label="Filter by name" value={name}
      onChange={event => setName(event.target.value)} />
  </>}
  onClearFilters={() => setName('')} />

